#!/usr/bin/env python3
"""Fixed, staged classroom actions; student entry points are generated by setup."""

from datetime import datetime, timezone
import json
import os
from pathlib import Path
import re
import shlex
import shutil
import socket
import subprocess
import sys
import time
import urllib.request


LAB = Path("/opt/ai-ran")
REPO = Path("/opt/oai-anomaly-detection")
RAN = Path("/opt/openairinterface5g/cmake_targets/ran_build/build")
FLEXRIC = Path("/opt/flexric/build")
LOGS = Path("/var/log/ai-ran")
STATE = Path("/var/tmp/ai-ran/state/runtime.json")
TMUX = ["tmux", "-L", "ai-ran"]
COMPOSE = ["docker", "compose", "--project-name", "slicing-cn", "-f",
           str(REPO / "slicing-cn/docker-compose-slicing-basic-nrf.yaml"), "-f", str(REPO / "powder/compose-pinned.yaml")]
NFS = ["oai-nssf", "oai_udr", "oai_udm", "oai_ausf", "oai_amf", "oai_smf_slice1",
       "oai_smf_slice2", "oai_upf_slice1", "oai_upf_slice2"]
CONTAINERS = ["mysql", "oai-ext-dn", "oai-nrf-slice12", "oai-nssf", "oai-udr", "oai-udm",
              "oai-ausf", "oai-amf", "oai-smf-slice1", "oai-smf-slice2", "oai-upf-slice1", "oai-upf-slice2"]


def state():
    return json.loads(STATE.read_text()) if STATE.exists() else {"core": False, "actors": [], "attack_run": False}


def record(**values):
    current = state()
    current.update(values)
    STATE.write_text(json.dumps(current, indent=2) + "\n")


def run(command, check=True, capture=False):
    command = list(map(str, command))
    text = shlex.join(command)
    with (LOGS / "commands.jsonl").open("a") as handle:
        handle.write(json.dumps({"utc": datetime.now(timezone.utc).isoformat(), "command": command}) + "\n")
    if not capture:
        print("+", text, flush=True)
    result = subprocess.run(command, text=True, capture_output=capture)
    if check and result.returncode:
        if capture:
            print(result.stdout, result.stderr, flush=True)
        raise RuntimeError(f"Command failed: {text}")
    return result


def wait_for(description, predicate, timeout=120):
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        try:
            if predicate():
                print("READY:", description, flush=True)
                return
        except (OSError, ValueError):
            pass
        time.sleep(1)
    raise RuntimeError(f"Timed out: {description}. Inspect {LOGS}.")


def contains(actor, expression):
    path = LOGS / f"{actor}.log"
    return path.exists() and re.search(expression, path.read_text(errors="replace")) is not None


def session(actor):
    return run(TMUX + ["has-session", "-t", actor], check=False, capture=True).returncode == 0


def need(*actors):
    for actor in actors:
        if actor not in state()["actors"] or not session(actor):
            raise RuntimeError(f"Start {actor} first using the lab procedure")


def spawn(actor, command, cwd=LAB):
    if session(actor):
        raise RuntimeError(f"{actor} is already running; no new connection will be created")
    path = LOGS / f"{actor}.log"
    if path.exists():
        archive = LOGS / "archive"
        archive.mkdir(exist_ok=True)
        shutil.copy2(path, archive / (datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ-") + path.name))
    actors = state()["actors"]
    if actor not in actors:
        record(actors=actors + [actor])
    shell = "exec " + shlex.join(list(map(str, command))) + " > " + str(path) + " 2>&1"
    run(TMUX + ["new-session", "-d", "-s", actor, "-c", str(cwd), shell])


def registered(kind):
    with urllib.request.urlopen("http://192.168.70.136:8080/nnrf-nfm/v1/nf-instances?nf-type=" + kind, timeout=2) as reply:
        return json.load(reply)["_links"]["item"]


def core():
    if state()["core"]:
        raise RuntimeError("This lab's core is already started; stop-lab before a fresh run")
    existing = run(["pgrep", "-af", r"(^|/)(nr-softmodem|nr-uesoftmodem|nearRT-RIC|xapp_rc_slice_ctrl)( |$)"], check=False, capture=True)
    if existing.returncode == 0:
        raise RuntimeError("Existing radio/controller actors must be stopped in their owning runtime first:\n" + existing.stdout)
    record(core=True, actors=[], attack_run=False)
    run(COMPOSE + ["up", "-d", "mysql", "oai_ext_dn"])
    run(COMPOSE + ["stop", "oai_nrf_slice12", *NFS])
    run(COMPOSE + ["up", "-d", "--no-deps", "--force-recreate", "oai_nrf_slice12"])
    wait_for("NRF API", lambda: registered("SMF") is not None)
    run(COMPOSE + ["up", "-d", "--no-deps", "--force-recreate", *NFS])
    wait_for("AMF and two SMF/UPF registrations", lambda: len(registered("AMF")) == 1 and
             len(registered("SMF")) == 2 and len(registered("UPF")) == 2)
    def healthy():
        result = run(["docker", "inspect", "--format", "{{.State.Running}} {{if .State.Health}}{{.State.Health.Status}}{{end}}", *CONTAINERS], capture=True)
        return len(result.stdout.splitlines()) == 12 and all(line == "true healthy" for line in result.stdout.splitlines())
    wait_for("12 healthy core containers", healthy)


def ric():
    if not state()["core"]:
        raise RuntimeError("Start the core first")
    spawn("ric", ["stdbuf", "-oL", "-eL", FLEXRIC / "examples/ric/nearRT-RIC",
                  "-c", LAB / "etc/flexric.conf", "-p", str(LAB / "lib/flexric") + "/"])
    wait_for("near-RT RIC listening", lambda: contains("ric", "Initializing Task Manager"))


def gnb():
    need("ric")
    spawn("gnb", ["stdbuf", "-oL", "-eL", "./nr-softmodem", "-O", LAB / "etc/gnb.conf",
                  "--sa", "--rfsim", "-E", "--gNBs.[0].min_rxtxtime", "6", "--telnetsrv", "--telnetsrv.shrmod", "rrc"], RAN)
    wait_for("gNB E2 setup and RRC module", lambda: contains("gnb", r"E2 SETUP[- ]RESPONSE") and
             contains("gnb", "libtelnetsrv_rrc.so successfully loaded"))


def ue(number):
    need("gnb")
    if number == 2:
        need("ue1")
    namespaces = {line.split()[0] for line in run(["ip", "netns", "list"], capture=True).stdout.splitlines()}
    if f"ue{number}" not in namespaces:
        run(["bash", REPO / "conf/multi-ue.sh", f"-c{number}"])
    spawn(f"ue{number}", ["ip", "netns", "exec", f"ue{number}", "env", "LD_LIBRARY_PATH=.",
                          "stdbuf", "-oL", "-eL", "./nr-uesoftmodem", "--rfsimulator.serveraddr", f"10.{200 + number}.1.100",
                          "-r", "106", "--numerology", "1", "--band", "78", "-C", "3619200000", "--rfsim", "--sa",
                          "-O", REPO / f"conf/ue_{number}.conf", "-E"], RAN)
    address = "12.2.1.2/" if number == 1 else "12.1.1.130/"
    def has_address():
        return address in run(["ip", "-n", f"ue{number}", "-o", "-4", "addr", "show", "dev", "oaitun_ue1"], check=False, capture=True).stdout
    wait_for(f"UE{number} PDU address {address[:-1]}", has_address)
    run(["ip", "-n", f"ue{number}", "route", "replace", "192.168.70.145/32", "dev", "oaitun_ue1"])
    wait_for(f"UE{number} DN ping", lambda: run(["ip", "netns", "exec", f"ue{number}", "ping", "-n", "-c", "1", "-W", "1", "192.168.70.145"],
             check=False, capture=True).returncode == 0, timeout=30)
    wait_for(f"CU UE ID {number}", lambda: contains("gnb", f"CU-UE-ID {number}"))


def xapp():
    need("ric", "gnb", "ue1", "ue2")
    spawn("xapp", ["stdbuf", "-oL", "-eL", FLEXRIC / "examples/xApp/c/ctrl/xapp_rc_slice_ctrl",
                   "-c", LAB / "etc/flexric.conf", "-p", str(LAB / "lib/flexric") + "/"])
    wait_for("xApp E42 connection; awaiting detector clients", lambda: contains("xapp", "Waiting for incoming connections"))


def detectors():
    need("xapp")
    for number in (1, 2):
        spawn(f"ads{number}", ["docker", "exec", "-w", "/app", f"oai-upf-slice{number}", "python3", "-u",
                               f"anomaly-detection-server-slice{number}.py"])
        wait_for(f"detector {number} TCP connection", lambda: contains("xapp", f"Connection accepted from client {number}"))
    wait_for("initial slice-control acknowledgment", lambda: contains("xapp", "RC initialization completed"))


def traffic(attack=False):
    need("ue1", "ue2", "xapp", "ads1", "ads2")
    if state()["attack_run"]:
        raise RuntimeError("This run has already exercised release. Use stop-lab and repeat the staged start sequence.")
    commands = []
    if attack:
        run(["ip", "-n", "ue1", "route", "replace", "unreachable", "12.2.1.0/24", "metric", "32760"])
        route = run(["ip", "-n", "ue1", "route", "get", "12.2.1.1"], capture=True).stdout
        if "dev oaitun_ue1" not in route or "src 12.2.1.2" not in route:
            raise RuntimeError("The attack destination is not on the UE1 lab path")
        commands = [(["ip", "netns", "exec", "ue1", "timeout", "-s", "INT", "-k", "2", "25",
                      "hping3", "-S", "-d", "100", "-a", "12.2.1.2", "12.2.1.1"], "attack-ue1.log"),
                    (["ip", "netns", "exec", "ue2", "ping", "-n", "-i", "0.2", "-c", "150", "-w", "32", "-W", "1", "192.168.70.145"], "attack-ue2.log")]
        record(attack_run=True)
    else:
        commands = [(["ip", "netns", "exec", f"ue{n}", "ping", "-n", "-i", "0.2", "-c", "30", "-w", "12", "-W", "1", "192.168.70.145"],
                     f"normal-ue{n}.log") for n in (1, 2)]
    processes = []
    try:
        for command, name in commands:
            with (LOGS / "commands.jsonl").open("a") as audit:
                audit.write(json.dumps({"utc": datetime.now(timezone.utc).isoformat(), "command": command}) + "\n")
            handle = (LOGS / name).open("w")
            process = subprocess.Popen(command, stdout=handle, stderr=subprocess.STDOUT, start_new_session=True)
            processes.append((process, handle, name))
        for process, handle, name in processes:
            code = process.wait(timeout=40)
            handle.close()
            print(f"{name}: exit {code}; see {LOGS / name}")
            if code not in ((0, 124) if attack else (0,)):
                raise RuntimeError(f"Traffic command did not complete normally: {name}")
    finally:
        for process, handle, _ in processes:
            if process.poll() is None:
                os.killpg(process.pid, 15)
            if not handle.closed:
                handle.close()
    if attack:
        print("Traffic finished. Stop both captures, then correlate reports, control requests, telnet, and UE/gNB logs.")
        print("UE1 RRC Release observed:", contains("ue1", "Received RRC Release"))
    else:
        wait_for("normal detector windows", lambda: contains("ads1", "Window results: 30 Normal, 0 Anomaly") and
                 contains("ads2", "Window results: 30 Normal, 0 Anomaly"), timeout=10)


def stop():
    current = state()
    for actor in ("ads1", "ads2", "xapp", "ue2", "ue1", "gnb", "ric"):
        if session(actor):
            run(TMUX + ["kill-session", "-t", actor])
    for number in (1, 2):
        if f"ads{number}" in current["actors"]:
            run(["docker", "exec", f"oai-upf-slice{number}", "pkill", "-f",
                 f"^python3.*anomaly-detection-server-slice{number}[.]py$"], check=False, capture=True)
    if current["core"]:
        run(COMPOSE + ["stop"])
    record(core=False, actors=[], attack_run=False)
    print("Stopped this lab's actors/core. Captures and logs are retained.")


def status():
    run(COMPOSE + ["ps"])
    run(TMUX + ["list-sessions"], check=False)
    for number in (1, 2):
        run(["ip", "-n", f"ue{number}", "-br", "address"], check=False)


def export_results():
    folder = Path("/var/tmp/ai-ran/exports")
    folder.mkdir(exist_ok=True)
    archive = folder / ("ai-ran-" + datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ") + ".tar.gz")
    run(["tar", "-czf", archive, "-C", "/", "var/tmp/ai-ran/captures", "var/log/ai-ran", "opt/ai-ran/setup-manifest.json"])
    archive.chmod(0o644)
    account = os.environ.get("SUDO_USER", "root")
    print("Run on your laptop (using your portal's SSH host if its alias differs):")
    print(f"scp {account}@{socket.getfqdn()}:{archive} .")


def main():
    actions = {"core": core, "ric": ric, "gnb": gnb, "ue1": lambda: ue(1), "ue2": lambda: ue(2),
               "xapp": xapp, "detectors": detectors, "normal": traffic, "attack": lambda: traffic(True),
               "stop": stop, "status": status, "export": export_results}
    if len(sys.argv) != 2 or sys.argv[1] not in actions:
        raise SystemExit("Use the fixed entry points in /opt/ai-ran/bin")
    if os.geteuid() != 0:
        raise SystemExit("Run the lab entry point with sudo")
    if not (LAB / "READY").exists() and sys.argv[1] not in ("stop", "status"):
        raise SystemExit("Profile preparation is incomplete; inspect /var/log/ai-ran/setup.log")
    LOGS.mkdir(parents=True, exist_ok=True)
    STATE.parent.mkdir(parents=True, exist_ok=True)
    try:
        actions[sys.argv[1]]()
    except (RuntimeError, subprocess.SubprocessError) as error:
        raise SystemExit(str(error))


if __name__ == "__main__":
    main()
